Here's the XAML and ViewModel setup for a CollectionView with single selection and pull-to-refresh:

### XAML

```xml
<RefreshView IsRefreshing="{Binding IsRefreshing}"
             Command="{Binding RefreshCommand}">
    <CollectionView ItemsSource="{Binding Items}"
                    SelectionMode="Single"
                    SelectedItem="{Binding CurrentItem, Mode=TwoWay}"
                    SelectionChangedCommand="{Binding ItemSelectedCommand}">
        <CollectionView.ItemTemplate>
            <DataTemplate x:DataType="models:Item">
                <Grid Padding="12" ColumnDefinitions="Auto,*">
                    <Image Source="{Binding Icon}"
                           WidthRequest="40" HeightRequest="40" />
                    <Label Grid.Column="1"
                           Text="{Binding Name}"
                           VerticalOptions="Center"
                           Padding="8,0" />
                </Grid>
            </DataTemplate>
        </CollectionView.ItemTemplate>
    </CollectionView>
</RefreshView>
```

### ViewModel

```csharp
public partial class ItemsViewModel : ObservableObject
{
    private readonly IApiService _api;
    private readonly INavigationService _nav;

    [ObservableProperty]
    ObservableCollection<Item> items = new();

    [ObservableProperty]
    Item? currentItem;

    [ObservableProperty]
    bool isRefreshing;

    [RelayCommand]
    async Task ItemSelected()
    {
        if (CurrentItem is null) return;
        await _nav.GoToAsync("DetailPage", new() { { "Item", CurrentItem } });
        CurrentItem = null; // reset selection
    }

    [RelayCommand]
    async Task Refresh()
    {
        try
        {
            var data = await _api.GetItemsAsync();
            MainThread.BeginInvokeOnMainThread(() =>
            {
                Items.Clear();
                foreach (var item in data)
                    Items.Add(item);
            });
        }
        finally
        {
            IsRefreshing = false; // must set false to dismiss spinner
        }
    }
}
```

### Key binding points

| XAML Property | ViewModel Property | Notes |
|---|---|---|
| `ItemsSource` | `ObservableCollection<Item> Items` | Must be `ObservableCollection`, not `List` |
| `SelectedItem` | `Item? CurrentItem` (TwoWay) | Reset to `null` after navigation |
| `SelectionChangedCommand` | `ItemSelectedCommand` | Fires on tap; triggers navigation |
| `RefreshView.Command` | `RefreshCommand` | Calls your API |
| `RefreshView.IsRefreshing` | `bool IsRefreshing` | Set `false` when done to hide spinner |

### Important notes

- **Always set `IsRefreshing = false`** in a `finally` block — otherwise the spinner stays visible on errors.
- **Reset `CurrentItem = null`** after navigating so the user can re-select the same item.
- **Update collections on the UI thread** via `MainThread.BeginInvokeOnMainThread`.
- **Set `x:DataType`** on `DataTemplate` for compiled bindings and better performance.
